import { randomUUID } from 'node:crypto';
import { createReadStream } from 'node:fs';
import { mkdir, rm, stat, writeFile } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';
import type { Readable } from 'node:stream';

// Local-disk storage for uploaded documents (medical certificates of minors: sensitive data).
// Safety rules: the stored name is generated by the server (the client file name is never used as a path),
// every resolved path must stay inside the storage root, and files are grouped per society.

export const MAX_UPLOAD_BYTES = 5 * 1024 * 1024;

export const ALLOWED_MIME_TYPES = ['application/pdf', 'image/jpeg', 'image/png'] as const;
export type AllowedMimeType = (typeof ALLOWED_MIME_TYPES)[number];

const EXTENSIONS: Record<AllowedMimeType, string> = {
  'application/pdf': 'pdf',
  'image/jpeg': 'jpg',
  'image/png': 'png',
};

export function isAllowedMimeType(value: string): value is AllowedMimeType {
  return (ALLOWED_MIME_TYPES as readonly string[]).includes(value);
}

const SIGNATURES: Record<AllowedMimeType, readonly number[]> = {
  'application/pdf': [0x25, 0x50, 0x44, 0x46, 0x2d],
  'image/jpeg': [0xff, 0xd8, 0xff],
  'image/png': [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a],
};

// The declared type proves nothing: check the magic bytes of the content.
export function matchesSignature(content: Buffer, mimeType: AllowedMimeType): boolean {
  return SIGNATURES[mimeType].every((byte, index) => content[index] === byte);
}

// Keeps letters, digits, dot, dash, underscore and space; drops any directory part. Used only for display and
// the Content-Disposition header, never for the path on disk.
export function sanitizeFileName(raw: string | undefined, fallback = 'documento'): string {
  const base = (raw ?? '').split(/[\\/]/).at(-1) ?? '';
  const printable = Array.from(base.normalize('NFKC'))
    .filter((char) => {
      const code = char.codePointAt(0) ?? 0;
      return code >= 32 && code !== 127;
    })
    .join('');
  const cleaned = printable
    .replace(/[^\p{L}\p{N}._ -]/gu, '_')
    .replace(/\.{2,}/g, '.')
    .replace(/^[.\s]+/, '')
    .trim();
  return cleaned === '' ? fallback : cleaned.slice(0, 100);
}

export interface FileStorage {
  save(societyId: string, content: Buffer, mimeType: AllowedMimeType): Promise<string>;
  open(fileKey: string): Promise<{ stream: Readable; sizeBytes: number }>;
  remove(fileKey: string): Promise<void>;
}

export function createFileStorage(rootDir: string): FileStorage {
  const root = resolve(rootDir);

  // Defence in depth: a key coming from the database must still resolve inside the root.
  function pathOf(fileKey: string): string {
    const target = resolve(root, fileKey);
    if (!target.startsWith(root + sep)) throw new Error('Storage key escapes the storage root');
    return target;
  }

  return {
    async save(societyId, content, mimeType) {
      const fileKey = `${societyId}/${randomUUID()}.${EXTENSIONS[mimeType]}`;
      const target = pathOf(fileKey);
      await mkdir(dirname(target), { recursive: true });
      await writeFile(target, content, { flag: 'wx', mode: 0o600 });
      return fileKey;
    },
    async open(fileKey) {
      const target = pathOf(fileKey);
      const info = await stat(target);
      return { stream: createReadStream(target), sizeBytes: info.size };
    },
    async remove(fileKey) {
      await rm(pathOf(fileKey), { force: true });
    },
  };
}
